use std :: path :: Path ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Checks whether `candidate` resolves to an existing absolute file or"] # [doc = " directory path."] # [doc = ""] # [doc = " Tries the raw string first, then falls back to un-escaping backslashes"] # [doc = " (for terminals that send `/path/my\\ file.txt`). Returns the resolved"] # [doc = " clean path on success, or `None` if no match was found."] fn resolve_file_path (candidate : & str) -> Option < String > { let path = Path :: new (candidate) ; if path . is_absolute () && path . exists () { return Some (candidate . to_string ()) ; } if let Some (unescaped) = unescape_backslashes (candidate) { let path = Path :: new (& unescaped) ; if path . is_absolute () && path . exists () { return Some (unescaped) ; } } None }